```python
def caesar_shift(s, k):
    result = []
    for ch in s:
        if ch.isalpha():
            ascii_offset = ord('a') if ch.islower() else ord('A')
            result.append(chr((ord(ch) - ascii_offset + k) % 26 + ascii_offset))
        else:
            result.append(ch)
    return ''.join(result)
```

